effect.shader:

    vec4 newLayer( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
    }

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord.xy

   /////////////////////////

        #define PHASE_POWER 1.0

        vec2 hash2( vec2 p )
        {
        	// texture based white noise
        	return texture2D( iChannel0.texture, (p+0.5)/256.0, -100.0 ).xy;

            // procedural white noise	
        	//return fract(sin(vec2(dot(p,vec2(127.1,311.7)),dot(p,vec2(269.5,183.3))))*43758.5453);
        }

        vec4 voronoi( in vec2 x )
        {
            vec2 n = floor(x);
            vec2 f = fract(x);
        	vec2 o;
            //----------------------------------
            // first pass: regular voronoi
            //----------------------------------
        	vec2 mg, mr;
        	float oldDist;

            float md = 8.0;
            for( int j=-1; j<=1; j++ )
            for( int i=-1; i<=1; i++ )
            {
                vec2 g = vec2(float(i),float(j));
        		o = hash2( n + g );
                vec2 r = g + o - f;
                float d = dot(r,r);

                if( d<md )
                {
                    md = d;
                    mr = r;
                    mg = g;
                }
            }

            oldDist = md;

            //----------------------------------
            // second pass: distance to borders
            //----------------------------------
            md = 8.0;
            for( int j=-2; j<=2; j++ )
            for( int i=-2; i<=2; i++ )
            {
                vec2 g = mg + vec2(float(i),float(j));
        		o = hash2( n + g );
                vec2 r = g + o - f;

                if( dot(mr-r,mr-r)>0.00001 )
                md = min( md, dot( 0.5*(mr+r), normalize(r-mr) ) );
            }

            return vec4( md, mr, oldDist );
        }

   /////////////////////////
    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        vec2 TanRyu;
        TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        TanRyu.y*=acLayerSize.y/acLayerSize.x;

        TanRyu /= scale;
        TanRyu *= rot2m((0.0+angle)*0.0174533);
        TanRyu += vec2((0.0+position.x), (250.0+position.y))*vec2(-1.,1.)/500.;


        /////////////////////////

        // if(progressa <= 0.0) { gl_FragColor = texture2DCv(inputImg.texture,acScreenNorm); }
        // else if(progressa >= 0.0001) { 

    	vec4 fragColor;

            vec2 uv = TanRyu;
            float pauseFreq = progressd;
            float pauseScale = 1.0; // range 0-1
            float scaledTime = progressb * 0.50;
            scaledTime += 0.05*uv.x;
            float sinTime = sin(pauseFreq*scaledTime);
            float sinTimeOffset = sin(pauseFreq*scaledTime - 0.5*3.141);
            float timeStep = scaledTime + pauseScale*(sinTime/pauseFreq);

            vec2 p = uv;
            vec4 c;


            p *= 4.0;
            // p.x += - timeStep*6.0;
            // p.y += - timeStep*3.0;    
            p.x = 0.5 - timeStep*3.0;
            p.y = 0.5 - timeStep*3.0; 
            c = voronoi( p );

            float cellPos = (p.y+c.z)+ timeStep*3.0;
            // uv.x += 0.5*(2.0 * cellPos-1.0) * (uv.y-0.5);
            uv.x += 1.5*(2.0 * c.x-0.33) * (uv.y-0.5);
        	// fragColor = vec4(2.5*(2.0 * cellPos-1.0) * (uv.y-0.5)); return;


            uv.x *= 0.25; 
            p = uv;
            p.y = max(p.y, 0.5); 
            p *= 12.0; // higher values zoom out further - don't go too high or the sine waves will become quite obvious...
            p.x += timeStep*16.0;
            p.y += timeStep*32.0;
            c = voronoi( p );
            // c.x = 1.0-pow(1.0-c.x, 2.0);


        	fragColor = 0.5*vec4(c.x);

            float d = 0.0;
            float edgeScale = 1.0-2.0*abs(progressa - 0.5);
            //edgeScale = fragCoord.x/iResolution.x ;
            float scaleMulti = pow(0.5*sinTime + 0.5, 2.0);
        	float dScale = 2.0 * edgeScale * (0.25+0.75*pow(0.5*sinTimeOffset + 0.5, 2.0));

            p.y = 0.5*12.0 + timeStep*3.0;
            c = dScale*voronoi( p );
            // float d = 1.0-abs(uv.y-c.x-0.25);
            d = (uv.y+c.x-0.75);

            p.x = uv.x*12.0 - timeStep*6.0;
            p.y = 4.5*12.0 - timeStep*3.0;
            c = dScale*voronoi( p );
            d = mix(d, (uv.y-c.x-0.25), 0.5);


            d = 1.0-abs(d);

            fragColor = vec4(d);
            //float lineWidth *= 1.0- pow(1.0-(0.5*sinTimeOffset + 0.5), 2.0);
            float lineWidth = d+progresse*scaleMulti *edgeScale;

        	fragColor = mix(vec4(color2), vec4(color3), scaleMulti) * smoothstep(1.0, 1.005, lineWidth);
        	//fragColor += edgeScale*vec4(1,1,1.0,1 ) * smoothstep(1.0, 1.005, lineWidth);

            fragColor += edgeScale*pow(scaleMulti*smoothstep(0.75, 1.005, lineWidth), 16.0) * 0.5*vec4(color4) ;

            fragColor += color1;

            // const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
            // vec4 gradmap;
            // float luminance = dot(fragColor.rgb, luminanceWeighting);
            // gradmap = mix(color1,color2,luminance)*fragColor.a;

    	// vec4 factorx = mix(fragColor,gradmap,alphab);
    	vec4 factor = mix(texColorX,fragColor,1.0);

        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            resultfinal = (factor * bright) * texColor.a;
        } else if( blendMode==1 ) {         // multiply
            factor *= bright;
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            factor *= bright;
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	vec4 gfinal = mix(texColor, resultfinal, alpha);

    	gl_FragColor = newLayer(texColor, gfinal) * texColor.a;
    	// }
    }
